### Instruction:
Develop a Node.js script that connects to a Redis database, stores key-value pairs, and retrieves values based on user input. The script should handle errors gracefully and provide informative messages.
PLAINFORMAT

### Response:
const redis = require('redis');
const readline = require('readline');

const client = redis.createClient({
  host: '127.0.0.1',
  port: 6379,
});

client.on('error', (err) => {
  console.error(`Error connecting to Redis: ${err}`);
  process.exit(1);
});

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

function storeKeyValue(key, value) {
  client.set(key, value, (err, reply) => {
    if (err) {
      console.error(`Error storing key-value pair: ${err}`);
    } else {
      console.log(`Stored key-value pair: {${key}: ${value}}`);
    }
  });
}

function getValue(key) {
  client.get(key, (err, value) => {
    if (err) {
      console.error(`Error retrieving value for key "${key}": ${err}`);
    } else if (value === null) {
      console.log(`No value found for key "${key}"`);
    } else {
      console.log(`Value for key "${key}": ${value}`);
    }
  });
}

function main() {
  rl.question('Enter command (store <key> <value> | get <key> | quit): ', (input) => {
    const [command, key, value] = input.split(' ');

    if (command === 'store') {
      storeKeyValue(key, value);
    } else if (command === 'get') {
      getValue(key);
    } else if (command === 'quit') {
      console.log('Exiting...');
      client.quit();
      rl.close();
      return;
    } else {
      console.log('Invalid command. Please try again.');
    }

    main();
  });
}

main();

