### Instruction:
Develop a Golang application that connects to a PostgreSQL database and performs basic CRUD operations on a "users" table. The users table should have fields for id, name, email, and age.


### Response:
To create a Golang application that connects to a PostgreSQL database and performs basic CRUD operations on a "users" table, follow these steps:

1. Install the necessary packages:
- First, you need to install the `pq` package which is a PostgreSQL driver for Go's `database/sql` package.
```bash
go get -u github.com/lib/pq
```

2. Create a new folder for your project and initialize it as a Go module:
```bash
mkdir go-postgres-crud
cd go-postgres-crud
go mod init example.com/go-postgres-crud
```

3. Create a `main.go` file in the root of your project folder.

4. Add the following code to `main.go`:

```go
package main

import (
	"database/sql"
	"fmt"
	"log"

	_ "github.com/lib/pq"
)

const (
	host     = "localhost"
	port     = 5432
	user     = "postgres"
	password = "your-password"
	dbname   = "your-db-name"
)

type User struct {
	ID    int
	Name  string
	Email string
	Age   int
}

func main() {
	psqlInfo := fmt.Sprintf("host=%s port=%d user=%s password=%s dbname=%s sslmode=disable",
		host, port, user, password, dbname)

	db, err := sql.Open("postgres", psqlInfo)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	err = db.Ping()
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("Successfully connected!")

	// Perform CRUD operations here
}
```
Replace `"your-password"` and `"your-db-name"` with your actual PostgreSQL password and database name.

5. Implement the CRUD functions:

Create a user:
```go
func createUser(db *sql.DB, user User) error {
	sqlStatement := `
	INSERT INTO users (name, email, age)
	VALUES ($1, $2, $3)
	RETURNING id`
	err := db.QueryRow(sqlStatement, user.Name, user.Email, user.Age).Scan(&user.ID)

	if err != nil {
		return err
	}

	fmt.Println("New record ID is:", user.ID)
	return nil
}
```

Read a user by ID:
```go
func getUserByID(db *sql.DB, id int) (*User, error) {
	sqlStatement := `SELECT id, name, email, age FROM users WHERE id=$1;`
	var user User
	row := db.QueryRow(sqlStatement, id)
	err := row.Scan(&user.ID, &user.Name, &user.Email, &user.Age)

	switch err {
	case sql.ErrNoRows:
		fmt.Println("No rows were returned!")
		return nil, err
	case nil:
		return &user, nil
	default:
		return nil, err
	}
}
```

Update a user by ID:
```go
func updateUserByID(db *sql.DB, id int, user User) error {
	sqlStatement := `
	UPDATE users
	SET name = $2, email = $3, age = $4
	WHERE id = $1;`

	res, err := db.Exec(sqlStatement, id, user.Name, user.Email, user.Age)
	if err != nil {
		return err
	}

	rowsAffected, err := res.RowsAffected()
	if err != nil {
		return err
	}

	fmt.Println("Number of records updated:", rowsAffected)
	return nil
}
```

Delete a user by ID:
```go
func deleteUserByID(db *sql.DB, id int) error {
	sqlStatement := `DELETE FROM users WHERE id = $1;`
	res, err := db.Exec(sqlStatement, id)
	if err != nil {
		return err
	}

	rowsAffected, err := res.RowsAffected()
	if err != nil {
		return err
	}

	fmt.Println("Number of records deleted:", rowsAffected)
	return nil
}
```

6. Use the CRUD functions in your `main` function:

```go
func main() {
	// ...

	// Create a user
	newUser := User{Name: "John Doe", Email: "john.doe@example.com", Age: 30}
	err = createUser(db, newUser)
	if err != nil {
		log.Fatal(err)
	}

	// Get a user by ID
	user, err := getUserByID(db, 1)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("User: %+v\n", user)

	// Update a user by ID
	updatedUser := User{Name: "Jane Doe", Email: "jane.doe@example.com", Age: 28}
	err = updateUserByID(db, 1, updatedUser)
	if err != nil {
		log.Fatal(err)
	}

	// Delete a user by ID
	err = deleteUserByID(db, 2)
	if err != nil {
		log.Fatal(err)
	}
}
```

7. Run your application:
```bash
go run main.go
```

This will connect to your PostgreSQL database and perform basic CRUD operations on the "users" table.

Make sure you have created the "users" table in your PostgreSQL database with the following schema:

```sql
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    age INTEGER NOT NULL
);
```

### Instruction:
$\triangle PQR$ has an area of $27\,\text{cm}^2$ and a base measuring $6$ cm. What is the height, $h,$ of $\triangle PQR?$ [asy]
draw((0,0)--(6,0)--(4,9)--cycle);
draw((4,.5)--(4.5,.5)--(4.5,0));
draw((4,9)--(4,0));
label("$h$",(4,4.5),E);
label("$Q$",(0,0),W);
label("$R$",(6,0),E);
label("$P$",(4,9),N);
label("6 cm",(3,0),S);
[/asy]

### Response:
The area of a triangle can be calculated using the formula $\mbox{Area}=\frac{1}{2}\times \mbox{base} \times \mbox{height}.$

The area is $27\,\text{cm}^2$ and the base measures $6\,\text{cm}.$ Substituting these values into the formula, $$A=\frac{1}{2}\times b \times h$$becomes $$27=\frac{1}{2} \times 6 \times h$$or $27=3h.$ Therefore, $h=9}\,\text{cm.$

### Instruction:
Equilateral triangle $DEF$ is inscribed in equilateral triangle $ABC$ as shown with $\overline{ED}\perp\overline{BC}.$ What is the ratio of the area of $\triangle DEF$ to the area of $\triangle
ABC$? [asy]
import olympiad; import geometry; size(100); defaultpen(linewidth(0.8));
draw(dir(90)--dir(210)--(dir(-30))--cycle);
pair[] inters = intersectionpoints(Circle(origin,1/sqrt(3)),dir(90)--dir(210)--(dir(-30))--cycle);
inters[5] = dir(210) + ((dir(-30) - dir(210))/3);
draw(inters[0]--inters[2]--inters[5]--cycle);
draw(rightanglemark(inters[2],inters[5],dir(210),4));
dot("$A$",dir(90),N);
dot("$C$",dir(210),W);
dot("$B$",dir(-30),E);
dot("$F$",inters[0],E);
dot("$E$",inters[2],W);
dot("$D$",inters[5],S);
[/asy]

### Response:
Since $\triangle CDE$ has a right angle at $D$ and $\angle C = 60^\circ,$ we can let $CD = x,$ $DE = x\sqrt{3},$ and $CE = 2x$ for some positive $x.$
[asy]
import olympiad; import geometry; size(100); defaultpen(linewidth(0.8));
draw(dir(90)--dir(210)--(dir(-30))--cycle);
pair[] inters = intersectionpoints(Circle(origin,1/sqrt(3)),dir(90)--dir(210)--(dir(-30))--cycle);
inters[5] = dir(210) + ((dir(-30) - dir(210))/3);
draw(inters[0]--inters[2]--inters[5]--cycle);
draw(rightanglemark(inters[2],inters[5],dir(210),4));
dot("$A$",dir(90),N);
dot("$C$",dir(210),W);
dot("$B$",dir(-30),E);
dot("$F$",inters[0],E);
dot("$E$",inters[2],W);
dot("$D$",inters[5],S);
label("$x$",dir(210)--inters[5],S);
label("$2x$",dir(210)--inters[2],W);
label("$x$",inters[2]--dir(90),W);
[/asy]Note that $\triangle AEF \cong \triangle CDE,$ because $\angle AEF = 180^\circ - \angle DEF - \angle CED = 180^\circ - 60^\circ - 30^\circ = 90^\circ,$ $\angle EAF = 60^\circ,$ and $EF = DE.$ Then $AE = CD = x,$ so the side length of $\triangle ABC$ is $AC = AE + EC = 2x + x = 3x.$

Finally, the ratio of the areas of the triangles is the square of the ratio of the side lengths: $$\left(\frac{DE}{AC}\right)^2=\left(\frac{x\sqrt{3}}{3x}\right)^2=\frac 13.$$

